// Generated by `just generate` from `src/plugins/claudetto/slices/checks/domain/failures.ts`. Edit the source and run `just generate`.
// The lines of the output of a failed command that the summary prints, cut to the bounds of the slice.
// The exit code says that the command failed. The summary does not read the text of the output to find why,
// because the text depends on the language of the runner, of the compiler, and of the tests.
// Runners print the report of a failure at the end, so the last lines of the output stand for it.

import { MAX_FAILURE_LINES, MAX_LINE_CHARS } from "../limits.ts";

/** The lines to print for a failed command, and the count of earlier lines that the bound left out. */
export interface Failures {
  readonly lines: readonly string[];
  readonly omitted: number;
}

/** The lines of `output` with no trailing blanks, and without the blank lines. */
export const nonBlankLines = (output: string): string[] =>
  output
    .split("\n")
    .map((line) => line.trimEnd())
    .filter((line) => line.trim() !== "");

/** The line, cut to `MAX_LINE_CHARS` when it is longer. */
export const cut = (line: string): string =>
  line.length > MAX_LINE_CHARS
    ? `${line.slice(0, MAX_LINE_CHARS - 3)}...`
    : line;

/** The last `MAX_FAILURE_LINES` non-blank lines of `output`, with the count of the lines before them. */
export const failureLines = (output: string): Failures => {
  const all = nonBlankLines(output);
  const omitted = Math.max(0, all.length - MAX_FAILURE_LINES);
  return { lines: all.slice(omitted).map(cut), omitted };
};
